// Valida dono do agendamento, status e política de antecedência (2h, §4).
const args = $input.first().json || {};
const row = $('Buscar Agendamento Atual').first().json || null;
const out = { appointment_id: args.appointment_id, wa_id: args.wa_id, new_start_at: args.new_start_at };
if (!row) return [{ json: { ...out, ok: false, reason: 'agendamento-nao-encontrado' } }];
if (row.wa_id !== args.wa_id) return [{ json: { ...out, ok: false, reason: 'nao-autorizado', row } }];
if (!['scheduled', 'confirmed'].includes(row.status)) return [{ json: { ...out, ok: false, reason: 'status-nao-permite-reagendamento', row } }];
const limite = new Date(Date.now() + 2 * 3600 * 1000); // CANCEL_MIN_HOURS=2 (ver .env.example)
const novo = new Date(args.new_start_at);
if (novo < limite) return [{ json: { ...out, ok: false, reason: 'Reagendamento exige 2h de antecedência', row } }];
return [{ json: { ...out, ok: true, reason: null, row, duration_minutes: row.duration_minutes } }];

// Verifica se o novo horário cabe no expediente e recalcula end_at.
const v = $('Validar Regra de Negócio').first().json;
if (!v.ok) return [{ json: { ...v } }];
const exp = $('Buscar Expediente do Novo Horário').first().json;
if (!exp || exp.closed) return [{ json: { ...v, ok: false, reason: 'fora-expediente' } }];
function paraMin(t) { if (!t) return null; const p = String(t).split(':').map(Number); return p[0] * 60 + p[1]; }
const start = new Date(v.new_start_at);
const end = new Date(start.getTime() + Number(v.duration_minutes) * 60000);
const sMin = start.getHours() * 60 + start.getMinutes();
const eMin = end.getHours() * 60 + end.getMinutes();
if (sMin < paraMin(exp.open_time) || eMin > paraMin(exp.close_time)) return [{ json: { ...v, ok: false, reason: 'duracao-indisponivel' } }];
const bIni = paraMin(exp.break_start); const bFim = paraMin(exp.break_end);
if (bIni !== null && bFim !== null && sMin < bFim && eMin > bIni) return [{ json: { ...v, ok: false, reason: 'fora-expediente' } }];
return [{ json: { ...v, ok: true, end_at: end.toISOString(), barber_id: v.row ? v.row.barber_id : null } }];

// Consolida validações e marca motivo de bloqueio.
const v = $('Validar Novo Horário e Calcular Fim').first().json;
if (!v.ok) return [{ json: { ...v, motivo: v.reason } }];
const conflito = $('Verificar Conflito no Novo Horário').first().json || null;
const motivo = (conflito && conflito.id) ? 'conflito' : null;
return [{ json: { ...v, motivo } }];

const linha = $('Atualizar Agendamento').first().json || {};
const v = $('Decisão Reagendamento').first().json;
return [{ json: { ok: true, appointment_id: linha.id || v.appointment_id, start_at: linha.start_at || v.new_start_at } }];
